import { useEffect, useRef, useState } from 'react';
import { useBlocker } from 'react-router-dom';
import { updateChapter } from '../novels/novel-api';
import type { Chapter } from '../novels/novel-types';
import { ApiClientError } from '../../shared/api/api-client';

export type DraftBuffer = { title: string; content: string; isVip: boolean; priceCoins: number };
type Backup = { value: DraftBuffer; version: number; savedAt: string };
type Slot = { version: number; saved: DraftBuffer; pending?: DraftBuffer; inFlight?: DraftBuffer; running?: Promise<void>; conflict?: boolean; retired?: boolean };
const same = (a: DraftBuffer, b: DraftBuffer) => JSON.stringify(a) === JSON.stringify(b);
export function useDraftPersistence(userId: string, chapterId: string) {
  const slots = useRef(new Map<string, Slot>());
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const account = useRef({ userId });
  if (account.current.userId !== userId) {
    // Retire the old session synchronously: a debounce/response from it must not
    // dispatch a queued write with the next account's authentication token.
    if (timer.current) clearTimeout(timer.current);
    for (const slot of slots.current.values()) { slot.retired = true; slot.pending = undefined; }
    slots.current = new Map();
    account.current = { userId };
  }
  const session = account.current;
  const current = useRef(chapterId); current.current = chapterId;
  const mounted = useRef(true);
  const [status, setStatus] = useState<'saved' | 'saving' | 'error'>('saved');
  const [error, setError] = useState('');
  const [recovery, setRecovery] = useState<Backup | null>(null);
  const [dirty, setDirty] = useState(false);
  const key = (id: string) => `storycraft-draft:${userId}:${id}`;
  const update = () => { if (mounted.current) setDirty([...slots.current.values()].some(slot => Boolean(slot.pending || slot.running))); };
  const notify = (id: string, value: typeof status, message='') => { if (account.current !== session) return; update(); if (mounted.current && current.current === id) { setStatus(value); setError(message); } };
  async function drain(id: string): Promise<void> {
    if (account.current !== session || !mounted.current) return;
    const slot = slots.current.get(id);
    if (!slot) return;
    if (slot.running) { await slot.running; if (slot.pending) return drain(id); return; }
    if (slot.conflict) throw Error('Bản nháp có xung đột. Hãy tải bản máy chủ hoặc xuất bản đang viết.');
    const run = async () => {
      while (slot.pending && !slot.retired && mounted.current && account.current === session) {
        const value = slot.pending; slot.pending = undefined;
        slot.inFlight = value;
        notify(id, 'saving');
        try {
          const result = await updateChapter(id, { ...value, autosave: true, expectedVersion: slot.version });
          slot.version = result.draftVersion ?? result.draft?.version ?? slot.version;
          slot.saved = value;
          if (!slot.pending && !slot.retired && mounted.current) {
            try { const backup = JSON.parse(localStorage.getItem(key(id)) ?? 'null') as Backup | null; if (backup && same(backup.value, value)) localStorage.removeItem(key(id)); } catch { /* In-memory draft remains available. */ }
          }
          notify(id, slot.pending ? 'saving' : 'saved');
        } catch (cause) {
          if (!slot.retired) slot.pending ??= value;
          slot.conflict = cause instanceof ApiClientError && cause.status === 409;
          notify(id, 'error', slot.conflict ? 'Có thay đổi từ phiên khác. Bản trên máy được giữ lại; chưa ghi đè bản máy chủ.' : 'Không lưu được bản nháp. Hãy thử lại hoặc tải bản đang viết về máy.');
          throw cause;
        } finally {
          slot.inFlight = undefined;
        }
      }
    };
    slot.running = run(); update();
    try { await slot.running; } finally { slot.running = undefined; update(); }
  }
  function initialize(chapter: Chapter, force=false) {
    if (account.current !== session) throw Error('Phiên tài khoản đã thay đổi.');
    const id = chapter.chapterId;
    const existing = slots.current.get(id);
    if (existing && (!force || existing.running)) { setRecovery(null); setStatus(existing.conflict ? 'error' : existing.pending || existing.running ? 'saving' : 'saved'); return existing.pending ?? existing.inFlight ?? existing.saved; }
    const value: DraftBuffer = { title: chapter.draft?.title ?? chapter.title, content: chapter.draft?.content ?? chapter.content ?? '', isVip: chapter.isVip, priceCoins: chapter.priceCoins };
    slots.current.set(id, { version: chapter.draft?.version ?? chapter.draftVersion ?? 0, saved: value });
    let backup: Backup | null = null;
    try { const stored = JSON.parse(localStorage.getItem(key(id)) ?? 'null') as Backup | null;
      if (stored?.value && typeof stored.value.title === 'string' && typeof stored.value.content === 'string' && typeof stored.value.isVip === 'boolean' && typeof stored.value.priceCoins === 'number' && !same(stored.value, value)) backup = stored;
    } catch { /* Corrupt/unavailable storage must not prevent writing. */ }
    setRecovery(backup); setStatus('saved'); setError(''); update(); return value;
  }
  function queue(value: DraftBuffer) {
    if (account.current !== session) return;
    const id = chapterId, slot = slots.current.get(id);
    if (!slot) return;
    if (timer.current) clearTimeout(timer.current);
    if (same(value, slot.saved) && !slot.running) { slot.pending = undefined; try { localStorage.removeItem(key(id)); } catch {} setStatus('saved'); update(); return; }
    slot.pending = { ...value };
    try { localStorage.setItem(key(id), JSON.stringify({ value, version: slot.version, savedAt: new Date().toISOString() })); }
    catch { setError('Không thể lưu dự phòng trên máy. Hãy giữ trang mở cho đến khi lưu thành công.'); }
    setStatus(slot.conflict ? 'error' : 'saving'); update();
    if (timer.current) clearTimeout(timer.current);
    timer.current = setTimeout(() => { void drain(id).catch(() => {}); }, 1200);
  }
  async function flush() {
    if (account.current !== session) throw Error('Phiên tài khoản đã thay đổi.');
    if (timer.current) clearTimeout(timer.current);
    await Promise.all([...slots.current.keys()].map(id => drain(id)));
    if (account.current !== session) throw Error('Phiên tài khoản đã thay đổi.');
    return slots.current.get(chapterId)?.version ?? 0;
  }
  function abandon() {
    if (account.current !== session) return;
    if (timer.current) clearTimeout(timer.current);
    for (const slot of slots.current.values()) { slot.retired = true; slot.pending = undefined; }
    slots.current.clear();
    update();
  }
  function dismissRecovery() { if (account.current !== session) return; try { localStorage.removeItem(key(chapterId)); } catch {} setRecovery(null); }
  useEffect(() => { setRecovery(null); setError(''); setStatus('saved'); update(); }, [userId]);
  useEffect(() => {
    mounted.current = true;
    const beforeUnload = (event: BeforeUnloadEvent) => { if ([...slots.current.values()].some(slot => slot.pending || slot.running)) { event.preventDefault(); event.returnValue = ''; } };
    window.addEventListener('beforeunload', beforeUnload);
    return () => { mounted.current = false; if (timer.current) clearTimeout(timer.current); window.removeEventListener('beforeunload', beforeUnload); };
  }, []);
  const blocker = useBlocker(({ currentLocation, nextLocation }) => dirty && currentLocation.pathname + currentLocation.search !== nextLocation.pathname + nextLocation.search);
  return { initialize, queue, flush, status, error, recovery, dismissRecovery, abandon, blocker, dirty };
}

import { AppError } from '../../core/errors/app-error.js';
import { ObjectId } from 'mongodb';
import { getMongoDatabase } from '../../core/database/mongo.js';

const collectionName = 'draft_chapters';

export type DraftChapterDocument = {
  _id?: ObjectId;
  chapterId: string;
  novelId: string;
  authorId: string;
  title: string;
  content: string;
  wordCount: number;
  version: number;
  autosave: boolean;
  lastAcceptedRevisionId?: string | null;
  lastAcceptedAt?: Date | null;
  createdAt: Date;
  updatedAt: Date;
  deletedAt?: Date | null;
  deletionReason?: string | null;
  restoredAt?: Date | null;
};

function collection() {
  return getMongoDatabase().collection<DraftChapterDocument>(collectionName);
}

export async function ensureDraftChapterIndexes() {
  await collection().createIndex({ chapterId: 1, updatedAt: -1 });
  await collection().createIndex({ novelId: 1, authorId: 1 });
  await collection().createIndex({ chapterId: 1 }, { unique: true });
}

export async function upsertDraftChapter(input: {
  chapterId: string;
  novelId: string;
  authorId: string;
  title: string;
  content: string;
  wordCount: number;
  autosave: boolean;
  lastAcceptedRevisionId?: string | null;
  expectedVersion?: number;
}) {
  const now = new Date();

  let saved;
  try { saved = await collection().findOneAndUpdate(
    { chapterId: input.chapterId, ...(input.expectedVersion !== undefined ? { version: input.expectedVersion } : {}) },
    {
      $set: {
        novelId: input.novelId,
        authorId: input.authorId,
        title: input.title,
        content: input.content,
        wordCount: input.wordCount,
        autosave: input.autosave,
        ...(input.lastAcceptedRevisionId !== undefined
          ? { lastAcceptedRevisionId: input.lastAcceptedRevisionId, lastAcceptedAt: now }
          : {}),
        deletedAt: null,
        deletionReason: null,
        updatedAt: now
      },
      $setOnInsert: {
        chapterId: input.chapterId,
        createdAt: now
      },
      $inc: {
        version: 1
      }
    },
    { upsert: input.expectedVersion === undefined || input.expectedVersion === 0, returnDocument: 'after' }
  );

  } catch (error) {
    if ((error as { code?: number }).code === 11000 && input.expectedVersion !== undefined) throw new AppError(409, 'DRAFT_CONFLICT', 'Bản nháp đã thay đổi ở phiên khác. Bản đang viết chưa bị ghi đè.');
    throw error;
  }
  if (!saved) throw new AppError(409, 'DRAFT_CONFLICT', 'Bản nháp đã thay đổi ở phiên khác.');
  return saved;
}

export async function syncDraftFromRevisionConditional(input: {
  chapterId: string;
  revisionId: string;
  title?: string;
  content: string;
  wordCount: number;
  acceptTimestamp: Date;
  novelId?: string;
  authorId?: string;
}): Promise<{ status: 'synced' | 'skipped_newer_draft'; draft?: DraftChapterDocument | null }> {
  const now = new Date();
  const existing = await collection().findOne({ chapterId: input.chapterId, deletedAt: null });
  if (existing) {
    if (existing.updatedAt && existing.updatedAt > input.acceptTimestamp) {
      return { status: 'skipped_newer_draft', draft: existing };
    }
  } else {
    // If draft does not exist yet, atomically create it with trusted ownership
    const newDraft: DraftChapterDocument = {
      novelId: input.novelId ?? '',
      chapterId: input.chapterId,
      authorId: input.authorId ?? '',
      title: input.title ?? 'Chương mới',
      content: input.content,
      wordCount: input.wordCount,
      version: 1,
      autosave: false,
      lastAcceptedRevisionId: input.revisionId,
      lastAcceptedAt: input.acceptTimestamp,
      createdAt: now,
      updatedAt: now,
      deletedAt: null
    };
    try {
      await collection().insertOne(newDraft as any);
      return { status: 'synced', draft: newDraft };
    } catch (err: any) {
      if (err?.code === 11000 || String(err?.message).includes('E11000')) {
        const found = await collection().findOne({ chapterId: input.chapterId, deletedAt: null });
        if (found && found.updatedAt && found.updatedAt > input.acceptTimestamp) {
          return { status: 'skipped_newer_draft', draft: found };
        }
      } else {
        throw err;
      }
    }
  }

  const result = await collection().updateOne(
    {
      chapterId: input.chapterId,
      $or: [
        { updatedAt: { $lte: input.acceptTimestamp } },
        { updatedAt: { $exists: false } }
      ]
    },
    {
      $set: {
        ...(input.title ? { title: input.title } : {}),
        ...(input.novelId ? { novelId: input.novelId } : {}),
        ...(input.authorId ? { authorId: input.authorId } : {}),
        content: input.content,
        wordCount: input.wordCount,
        lastAcceptedRevisionId: input.revisionId,
        lastAcceptedAt: input.acceptTimestamp,
        updatedAt: now
      },
      $inc: { version: 1 }
    }
  );


  if (result.matchedCount === 0 && existing) {
    return { status: 'skipped_newer_draft', draft: existing };
  }

  const updated = await findDraftChapterByChapterId(input.chapterId);
  return { status: 'synced', draft: updated };
}

export async function findDraftChapterByChapterId(chapterId: string) {
  return collection().findOne({ chapterId, deletedAt: null });
}

export async function markDraftChaptersDeletedByNovelId(novelId: string, reason: string | undefined) {
  const now = new Date();
  return collection().updateMany(
    { novelId, deletedAt: null },
    {
      $set: {
        deletedAt: now,
        deletionReason: reason ?? null,
        updatedAt: now
      }
    }
  );
}

export async function restoreDraftChaptersByNovelId(novelId: string) {
  const now = new Date();
  return collection().updateMany(
    { novelId, deletedAt: { $ne: null } },
    {
      $set: {
        deletedAt: null,
        deletionReason: null,
        restoredAt: now,
        updatedAt: now
      }
    }
  );
}

import { z } from 'zod';

export const novelIdParamSchema = z.object({
  params: z.object({
    novelId: z.string().uuid()
  })
});

export const chapterIdParamSchema = z.object({
  params: z.object({
    chapterId: z.string().uuid()
  })
});

export const createChapterSchema = z.object({
  params: novelIdParamSchema.shape.params,
  body: z.object({
    title: z.string().min(1).max(100),
    content: z.string().default(''),
    clientRequestId: z.string().min(1).max(128).optional(),
    isVip: z.boolean().default(false),
    priceCoins: z.number().int().min(0).default(0)
  })
});

export const updateChapterSchema = z.object({
  params: chapterIdParamSchema.shape.params,
  body: z.object({
    title: z.string().min(1).max(100).optional(),
    content: z.string().optional(),
    isVip: z.boolean().optional(),
    priceCoins: z.number().int().min(0).optional(),
    expectedVersion: z.number().int().min(0).optional(),
    autosave: z.boolean().default(false)
  })
});

export type CreateChapterInput = z.infer<typeof createChapterSchema>['body'];
export type UpdateChapterInput = z.infer<typeof updateChapterSchema>['body'];

import type { PoolClient } from 'pg';
import { createHash } from 'node:crypto';
import { assertActiveAccount } from '../../core/security/active-account.js';
import { readNovel } from './novels.service.js';
import { withPostgresTransaction } from '../../core/database/transaction.js';
import { AppError } from '../../core/errors/app-error.js';
import type { AuthContext } from '../../core/security/auth-context.js';
import { checkContent } from '../content-control/content-control.service.js';
import type { CreateChapterInput, UpdateChapterInput } from './chapters.schemas.js';
import {
  createChapter as createChapterRow,
  findChapterById,
  getNextChapterNumber,
  listChaptersByNovelId,
  listPublicationSchedules,
  publishChapter,
  submitChapterForPublish,
  updateChapterMetadata,
  touchChapterUpdatedAt,
  updateChapterPricing
} from './chapters.repository.js';
import { findDraftChapterByChapterId, upsertDraftChapter } from './draft-chapters.repository.js';
import { getNovel } from './novels.service.js';

function countWords(content: string) {
  return content.trim().split(/\s+/).filter(Boolean).length;
}

function assertOwner(resource: { authorId: string }, auth: AuthContext) {
  if (auth.role === 'ADMIN') {
    return;
  }

  if (resource.authorId !== auth.userId) {
    throw new AppError(403, 'CONTENT_005', 'Content ownership required');
  }
}

function assertPremiumPricing(input: { isVip: boolean; priceCoins: number }) {
  if (input.isVip && input.priceCoins <= 0) {
    throw new AppError(400, 'VALIDATION_001', 'Premium chapter requires priceCoins greater than 0');
  }

  if (!input.isVip && input.priceCoins !== 0) {
    throw new AppError(400, 'VALIDATION_001', 'Free chapter requires priceCoins to be 0');
  }
}

export async function createChapter(auth: AuthContext, novelId: string, input: CreateChapterInput) {
  const novel = await getNovel(novelId);
  assertOwner(novel, auth);
  assertPremiumPricing({ isVip: input.isVip, priceCoins: input.priceCoins });

  const importHash = createHash('sha256').update(JSON.stringify([input.title, input.content, input.isVip, input.priceCoins])).digest('hex');
  const wordCount = countWords(input.content);
  const chapter = await withPostgresTransaction(async (client) => {
    const chapterNumber = await getNextChapterNumber(client, novelId);
    if (input.clientRequestId) {
      const prior = (await client.query('select * from chapters where novel_id = $1 and import_key = $2', [novelId, input.clientRequestId])).rows[0];
      if (prior) {
        if (prior.import_hash !== importHash || prior.deleted_at) throw new AppError(409, 'IMPORT_CONFLICT', 'Mã nhập đã được dùng cho nội dung khác hoặc chương đã xóa');
        return { chapterId: prior.chapter_id, novelId, title: prior.title, chapterNumber: prior.chapter_number, content: prior.content, wordCount: prior.word_count, isVip: prior.is_vip, priceCoins: prior.price_coins, status: prior.status, updatedAt: prior.updated_at, publicationSchedule: null };
      }
    }

    return createChapterRow(client, {
      novelId,
      title: input.title,
      chapterNumber,
      importKey: input.clientRequestId,
      importHash,
      wordCount,
      isVip: input.isVip,
      priceCoins: input.priceCoins
    });
  });

  const draft = await findDraftChapterByChapterId(chapter.chapterId) ?? await upsertDraftChapter({
    chapterId: chapter.chapterId,
    expectedVersion: 0,
    novelId,
    authorId: auth.userId,
    title: input.title,
    content: input.content,
    wordCount,
    autosave: false
  });

  return {
    ...chapter,
    draftVersion: draft?.version ?? 1
  };
}

export async function listChapters(novelId: string, auth?: AuthContext) {
  const novel = await readNovel(novelId, auth);
  const rows = await listChaptersByNovelId(novelId);
  if (auth && (auth.userId === novel.authorId || auth.role === 'ADMIN')) { const schedules = await listPublicationSchedules(novelId); return rows.map(chapter => ({ ...chapter, publicationSchedule: schedules.get(chapter.chapterId) ?? null })); }
  return rows.filter(chapter => chapter.status === 'PUBLISHED').map(({ publicationSchedule: _schedule, ...chapter }) => ({ ...chapter, content: null }));
}

export async function getChapter(chapterId: string, auth: AuthContext) {
  await assertActiveAccount(auth);
  const chapter = await findChapterById(chapterId);

  if (!chapter) {
    throw new AppError(404, 'CONTENT_001', 'Content not found');
  }

  const novel = await getNovel(chapter.novelId);
  assertOwner(novel, auth);
  const draft = await findDraftChapterByChapterId(chapterId);

  return {
    ...chapter,
    publicationSchedule: (await listPublicationSchedules(chapter.novelId)).get(chapterId) ?? null,
    draft: draft
      ? {
          title: draft.title,
          content: draft.content,
          wordCount: draft.wordCount,
          version: draft.version,
          autosave: draft.autosave,
          updatedAt: draft.updatedAt
        }
      : null
  };
}

export async function updateChapter(auth: AuthContext, chapterId: string, input: UpdateChapterInput) {
  return withPostgresTransaction(async client => {
  await client.query('select chapter_id from chapters where chapter_id = $1 for update', [chapterId]);
  const chapter = await findChapterById(chapterId);

  if (!chapter) {
    throw new AppError(404, 'CONTENT_001', 'Content not found');
  }

  const novel = await getNovel(chapter.novelId);
  assertOwner(novel, auth);

  const isPublishedPricingOnlyUpdate =
    chapter.status === 'PUBLISHED' &&
    (input.isVip !== undefined || input.priceCoins !== undefined) &&
    input.title === undefined &&
    input.content === undefined;

  if (!['DRAFT', 'REJECTED', 'PENDING_MODERATION', 'PUBLISHED'].includes(chapter.status) && !isPublishedPricingOnlyUpdate) {
    throw new AppError(409, 'CONTENT_004', 'Invalid content state');
  }

  const existingDraft = await findDraftChapterByChapterId(chapterId);
  const nextTitle = input.title ?? existingDraft?.title ?? chapter.title;
  const nextContent = input.content ?? existingDraft?.content ?? chapter.content ?? '';
  const wordCount = countWords(nextContent);
  const nextIsVip = input.isVip ?? chapter.isVip;
  const nextPriceCoins = input.priceCoins ?? (nextIsVip ? chapter.priceCoins : 0);
  assertPremiumPricing({ isVip: nextIsVip, priceCoins: nextPriceCoins });

  const isPublishedDraftUpdate =
    chapter.status === 'PUBLISHED' && (input.title !== undefined || input.content !== undefined) && !isPublishedPricingOnlyUpdate;

  let draft = existingDraft;
  if ((input.title !== undefined || input.content !== undefined) && input.expectedVersion === undefined) throw new AppError(428, 'DRAFT_VERSION_REQUIRED', 'Đọc phiên bản bản nháp trước khi lưu');

  if (input.title !== undefined || input.content !== undefined) {
    draft = await upsertDraftChapter({
      chapterId,
      novelId: chapter.novelId,
      authorId: auth.userId,
      title: nextTitle,
      content: nextContent,
      wordCount,
      autosave: input.autosave,
      expectedVersion: input.expectedVersion
    });
    await client.query("update chapter_publication_schedules set status='CANCELLED', error='Bản thảo đã thay đổi; hãy đặt lịch lại.', updated_at=now() where chapter_id=$1 and status='PENDING'", [chapterId]);
    if (isPublishedDraftUpdate) await touchChapterUpdatedAt(chapterId, client);
  }

  let updatedChapter;

  if (isPublishedDraftUpdate) {
    updatedChapter =
      input.isVip !== undefined || input.priceCoins !== undefined
        ? await updateChapterPricing(chapterId, {
            isVip: nextIsVip,
            priceCoins: nextPriceCoins
          }, client)
        : chapter;
  } else if (isPublishedPricingOnlyUpdate) {
    updatedChapter = await updateChapterPricing(chapterId, {
      isVip: nextIsVip,
      priceCoins: nextPriceCoins
    }, client);
  } else {
    updatedChapter = await updateChapterMetadata(chapterId, {
      title: input.title,
      wordCount,
      isVip: nextIsVip,
      priceCoins: nextPriceCoins
    }, client);
  }

  if (!updatedChapter) {
    throw new AppError(409, 'CONTENT_004', 'Invalid content state');
  }


  return {
    ...updatedChapter,
    draft: draft ? { title: draft.title, content: draft.content, wordCount: draft.wordCount, version: draft.version, autosave: draft.autosave, updatedAt: draft.updatedAt } : null,
    draftVersion: draft?.version ?? null
  };
  });
}

export async function submitChapterPublish(auth: AuthContext, chapterId: string, client?: PoolClient): Promise<{ chapterId: string; status: string; moderationRequired: boolean; moderationReviewId: string | null }> {
  if (!client) return withPostgresTransaction(async transaction => {
    await transaction.query('select chapter_id from chapters where chapter_id=$1 for update', [chapterId]);
    return submitChapterPublish(auth, chapterId, transaction);
  });
  const chapter = await findChapterById(chapterId);

  if (!chapter) {
    throw new AppError(404, 'CONTENT_001', 'Content not found');
  }

  const novel = await getNovel(chapter.novelId);
  assertOwner(novel, auth);

  if (!['DRAFT', 'REJECTED', 'PENDING_MODERATION', 'PUBLISHED'].includes(chapter.status)) {
    throw new AppError(409, 'CONTENT_004', 'Invalid content state');
  }

  const draft = await findDraftChapterByChapterId(chapterId);
  const publishTitle = draft?.title ?? chapter.title;
  const publishContent = draft?.content ?? chapter.content;
  const publishWordCount = draft?.wordCount ?? chapter.wordCount;

  if (!publishContent) {
    throw new AppError(409, 'CONTENT_004', 'Invalid content state');
  }

  const moderation = await checkContent({
    targetType: 'CHAPTER',
    targetId: chapter.chapterId,
    content: `${publishTitle}\n\n${publishContent}`,
    submittedBy: auth.userId,
    publicationSnapshot: { title: publishTitle, content: publishContent, wordCount: publishWordCount }
  }, client);

  await client.query("update chapter_publication_schedules set status='CANCELLED', error='Đã gửi phát hành thủ công.', updated_at=now() where chapter_id=$1 and status='PENDING'", [chapterId]);
  if (!moderation.moderationRequired) {
    const publishedChapter = await publishChapter(chapterId, {
      title: publishTitle,
      content: publishContent,
      wordCount: publishWordCount
    }, client);

    if (!publishedChapter) {
      throw new AppError(409, 'CONTENT_004', 'Invalid content state');
    }

    await client.query("update chapter_publication_schedules set status='CANCELLED', error='Đã phát hành phiên bản mới thủ công.', updated_at=now() where chapter_id=$1 and status='PENDING_MODERATION'", [chapterId]);
    return {
      chapterId: publishedChapter.chapterId,
      status: publishedChapter.status,
      moderationRequired: false,
      moderationReviewId: null
    };
  }

  const updatedChapter = chapter.status === 'PENDING_MODERATION' ? chapter : await submitChapterForPublish(chapterId, client);
  if (!updatedChapter) {
    throw new AppError(409, 'CONTENT_004', 'Invalid content state');
  }

  return {
    chapterId: updatedChapter.chapterId,
    status: updatedChapter.status,
    moderationRequired: true,
    moderationReviewId: moderation.moderationReviewId
  };
}

